!function(l){"use strict";l("#sidebarToggle, #sidebarToggleTop").on("click",function(e){l("body").toggleClass("sidebar-toggled"),l(".sidebar").toggleClass("toggled"),l(".sidebar").hasClass("toggled")&&l(".sidebar .collapse").collapse("hide")}),l(window).resize(function(){l(window).width()<768&&l(".sidebar .collapse").collapse("hide"),l(window).width()<480&&!l(".sidebar").hasClass("toggled")&&(l("body").addClass("sidebar-toggled"),l(".sidebar").addClass("toggled"),l(".sidebar .collapse").collapse("hide"))}),l("body.fixed-nav .sidebar").on("mousewheel DOMMouseScroll wheel",function(e){var o;768<l(window).width()&&(o=(o=e.originalEvent).wheelDelta||-o.detail,this.scrollTop+=30*(o<0?1:-1),e.preventDefault())}),l(document).on("scroll",function(){100<l(this).scrollTop()?l(".scroll-to-top").fadeIn():l(".scroll-to-top").fadeOut()}),l(document).on("click","a.scroll-to-top",function(e){var o=l(this);l("html, body").stop().animate({scrollTop:l(o.attr("href")).offset().top},1e3,"easeInOutExpo"),e.preventDefault()})}(jQuery);

(function($) {
  "use strict";

  function parseGradeNumber(value) {
    if (value === null || value === undefined) return null;
    var text = String(value).trim().replace(',', '.');
    if (!text || text === '—' || text === '-') return null;
    var num = parseFloat(text);
    return isNaN(num) ? null : num;
  }

  function roundGrade(score) {
    return score === null || score === undefined || isNaN(score) ? null : Math.round(Number(score));
  }

  function gradeStatus(score) {
    score = roundGrade(score);
    if (score === null) {
      return { letter: '—', label: 'Sin datos', className: 'ir-status-none', color: '#858796' };
    }
    if (score >= 18) {
      return { letter: 'AD', label: 'Logro destacado', className: 'ir-status-ad', color: '#13855c' };
    }
    if (score >= 14) {
      return { letter: 'A', label: 'Logro esperado', className: 'ir-status-a', color: '#1cc88a' };
    }
    if (score >= 11) {
      return { letter: 'B', label: 'En proceso', className: 'ir-status-b', color: '#f6c23e' };
    }
    return { letter: 'C', label: 'En inicio', className: 'ir-status-c', color: '#e74a3b' };
  }

  function statusBadge(status, extraClass) {
    return $('<span>', {
      class: 'ir-status-badge ' + status.className + (extraClass ? ' ' + extraClass : ''),
      text: status.letter + ' · ' + status.label
    });
  }

  function ensureStyles() {
    if (document.getElementById('grades-individual-status-styles')) return;
    var css = [
      '.individual-report .ir-result{min-width:190px;text-align:center;position:relative;overflow:hidden;transition:.2s ease}',
      '.individual-report .ir-result.ir-result-status{border-width:2px}',
      '.individual-report .ir-result .ir-final-status{display:inline-flex;margin-top:7px}',
      '.individual-report .ir-status-badge{display:inline-flex;align-items:center;justify-content:center;padding:5px 10px;border-radius:999px;font-size:.76rem;font-weight:700;line-height:1.1;border:1px solid transparent;white-space:nowrap}',
      '.individual-report .ir-status-ad{background:#d8f3e8;color:#0f6848;border-color:#9edfc8}',
      '.individual-report .ir-status-a{background:#e0f7ee;color:#107354;border-color:#abe8d2}',
      '.individual-report .ir-status-b{background:#fff5d6;color:#856404;border-color:#f5d77c}',
      '.individual-report .ir-status-c{background:#fde3e1;color:#a3281d;border-color:#f3aaa4}',
      '.individual-report .ir-status-none{background:#f1f3f5;color:#6c757d;border-color:#d8dde2}',
      '.individual-report .ir-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:0 0 18px}',
      '.individual-report .ir-summary-item{border:1px solid #e3e6f0;border-radius:8px;padding:10px 12px;background:#fff}',
      '.individual-report .ir-summary-item small{display:block;color:#7b8499;font-size:.72rem;margin-bottom:3px}',
      '.individual-report .ir-summary-item strong{display:block;font-size:1.25rem;color:#344767}',
      '.individual-report .ir-summary-item .ir-summary-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}',
      '.individual-report .ir-comp-status{margin-left:auto}',
      '.individual-report .ir-card-header .badge+.ir-comp-status{margin-left:0}',
      '.individual-report .ir-trend-card{border:1px solid #e3e6f0;border-radius:9px;background:#fff;margin:0 0 18px;overflow:hidden}',
      '.individual-report .ir-trend-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 14px;background:#f8f9fc;border-bottom:1px solid #e3e6f0}',
      '.individual-report .ir-trend-head h4{margin:0;font-size:.95rem;font-weight:700}',
      '.individual-report .ir-trend-head small{color:#7b8499}',
      '.individual-report .ir-trend-body{padding:14px}',
      '.individual-report .ir-trend-chart{width:100%;overflow-x:auto}',
      '.individual-report .ir-trend-chart svg{display:block;width:100%;min-width:620px;height:auto}',
      '.individual-report .ir-trend-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:12px}',
      '.individual-report .ir-trend-metric{border:1px solid #e3e6f0;border-radius:8px;padding:9px 11px;background:#fff}',
      '.individual-report .ir-trend-metric small{display:block;color:#7b8499;font-size:.72rem;margin-bottom:2px}',
      '.individual-report .ir-trend-metric strong{display:block;color:#344767;font-size:1.08rem}',
      '.individual-report .ir-trend-note{margin-top:12px;padding:10px 12px;border-radius:7px;background:#f8f9fc;border-left:4px solid #4e73df;color:#596579;font-size:.84rem}',
      '.individual-report .ir-trend-loading{padding:24px;text-align:center;color:#7b8499}',
      '.individual-report .ir-var-up{color:#13855c!important}.individual-report .ir-var-down{color:#e74a3b!important}.individual-report .ir-var-flat{color:#858796!important}',
      '@media(max-width:767px){.individual-report .ir-summary-grid,.individual-report .ir-trend-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.individual-report .ir-result{width:100%}}',
      '@media print{.individual-report .ir-status-badge,.individual-report .ir-summary-item,.individual-report .ir-result,.individual-report .ir-trend-card,.individual-report .ir-trend-metric{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}.individual-report .ir-summary-grid,.individual-report .ir-trend-metrics{grid-template-columns:repeat(4,minmax(0,1fr))!important}.individual-report .ir-trend-chart{overflow:visible!important}.individual-report .ir-trend-chart svg{min-width:0!important}}'
    ].join('');
    $('<style>', { id: 'grades-individual-status-styles', text: css }).appendTo('head');
  }

  function roundDisplayedCalculationGrades($report) {
    $report.find('.ir-card table').each(function() {
      var $table = $(this);
      var headers = [];
      $table.find('thead th').each(function(index) {
        headers[index] = $.trim($(this).text()).toLowerCase();
      });

      $table.find('tbody tr').each(function() {
        $(this).find('td,th').each(function(index) {
          if (headers[index] !== 'promedio') return;
          var $cell = $(this);
          var value = parseGradeNumber($cell.text());
          if (value === null) return;
          $cell.text(roundGrade(value));
        });
      });

      var $finalCell = $table.find('tfoot tr').last().find('td,th').last();
      if ($finalCell.length) {
        var finalValue = parseGradeNumber($finalCell.text());
        if (finalValue !== null) $finalCell.text(roundGrade(finalValue));
      }
    });
  }

  function trendRequestData(bimestre) {
    return {
      course_id: $('#course_id').val() || '',
      grado: $('#grado').val() || '',
      seccion: $('#seccion').val() || '',
      bimestre: String(bimestre),
      student_id: $('#student_id').val() || '',
      evaluation_id: '',
      level: $('#level').val() || '',
      academic_year_id: $('#academic_year_id').val() || '',
      show_avg: 1
    };
  }

  function extractScoreFromReportHtml(html) {
    try {
      var doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
      var node = doc.querySelector('.individual-report .ir-result strong');
      if (!node) return null;
      return roundGrade(parseGradeNumber(node.textContent));
    } catch (e) {
      return null;
    }
  }

  function fetchBimesterScore(bimestre) {
    return new Promise(function(resolve) {
      $.ajax({
        url: 'grades_report_table.php',
        method: 'POST',
        data: trendRequestData(bimestre)
      }).done(function(resp) {
        resolve(extractScoreFromReportHtml(resp));
      }).fail(function() {
        resolve(null);
      });
    });
  }

  function escapeSvgText(value) {
    return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function buildTrendSvg(scores, selectedBimester) {
    var width = 760, height = 270, left = 58, right = 28, top = 28, bottom = 46;
    var plotW = width - left - right, plotH = height - top - bottom;
    var xs = [0,1,2,3].map(function(i){ return left + (plotW / 3) * i; });
    function y(score) { return top + plotH - (Math.max(0, Math.min(20, score)) / 20) * plotH; }

    var out = [];
    out.push('<svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Tendencia de notas por bimestre">');
    out.push('<rect x="0" y="0" width="'+width+'" height="'+height+'" rx="8" fill="#ffffff"/>');

    [0,5,10,15,20].forEach(function(mark){
      var yy = y(mark);
      out.push('<line x1="'+left+'" y1="'+yy+'" x2="'+(width-right)+'" y2="'+yy+'" stroke="#e9edf4" stroke-width="1"/>');
      out.push('<text x="'+(left-12)+'" y="'+(yy+4)+'" text-anchor="end" font-size="11" fill="#858796">'+mark+'</text>');
    });

    for (var i=0;i<3;i++) {
      if (scores[i] === null || scores[i+1] === null) continue;
      out.push('<line x1="'+xs[i]+'" y1="'+y(scores[i])+'" x2="'+xs[i+1]+'" y2="'+y(scores[i+1])+'" stroke="#4e73df" stroke-width="4" stroke-linecap="round"/>');
    }

    scores.forEach(function(score, i){
      var labelX = xs[i];
      out.push('<text x="'+labelX+'" y="'+(height-18)+'" text-anchor="middle" font-size="12" font-weight="600" fill="#596579">'+(i+1)+'° Bim.</text>');
      if (score === null) {
        out.push('<circle cx="'+labelX+'" cy="'+y(0)+'" r="5" fill="#d8dde2"/>');
        out.push('<text x="'+labelX+'" y="'+(y(0)-12)+'" text-anchor="middle" font-size="11" fill="#858796">Sin nota</text>');
        return;
      }
      var status = gradeStatus(score);
      var yy = y(score);
      if (selectedBimester === i+1) out.push('<circle cx="'+labelX+'" cy="'+yy+'" r="13" fill="none" stroke="'+status.color+'" stroke-width="2" opacity=".35"/>');
      out.push('<circle cx="'+labelX+'" cy="'+yy+'" r="8" fill="'+status.color+'" stroke="#ffffff" stroke-width="3"/>');
      out.push('<text x="'+labelX+'" y="'+(yy-15)+'" text-anchor="middle" font-size="13" font-weight="700" fill="#344767">'+escapeSvgText(score)+'</text>');
    });

    out.push('</svg>');
    return out.join('');
  }

  function trendInterpretation(scores) {
    var valid = [];
    scores.forEach(function(score, index){ if (score !== null) valid.push({bim:index+1, score:score}); });
    if (valid.length < 2) return 'Aún no hay suficientes bimestres con notas para determinar una tendencia.';
    var first = valid[0], last = valid[valid.length-1], delta = last.score - first.score;
    if (delta >= 2) return 'Tendencia ascendente: el rendimiento mejora '+delta+' punto'+(delta === 1 ? '' : 's')+' entre el '+first.bim+'° y el '+last.bim+'° bimestre.';
    if (delta <= -2) return 'Tendencia descendente: el rendimiento disminuye '+Math.abs(delta)+' punto'+(Math.abs(delta) === 1 ? '' : 's')+' entre el '+first.bim+'° y el '+last.bim+'° bimestre.';
    return 'Tendencia estable: el rendimiento se mantiene con una variación global de '+(delta > 0 ? '+' : '')+delta+' punto'+(Math.abs(delta) === 1 ? '' : 's')+'.';
  }

  function renderTrend($report, scores) {
    var selectedBimester = parseInt($('#bimestre').val(), 10) || 0;
    var valid = scores.filter(function(v){ return v !== null; });
    var annual = valid.length ? roundGrade(valid.reduce(function(a,b){ return a+b; },0) / valid.length) : null;
    var bestScore = null, bestBimester = null;
    scores.forEach(function(score,index){
      if (score !== null && (bestScore === null || score > bestScore)) { bestScore = score; bestBimester = index+1; }
    });
    var currentScore = selectedBimester ? scores[selectedBimester-1] : null;
    var prevScore = selectedBimester > 1 ? scores[selectedBimester-2] : null;
    var variation = currentScore !== null && prevScore !== null ? currentScore - prevScore : null;
    var variationText = '—', variationClass = 'ir-var-flat';
    if (variation !== null) {
      if (variation > 0) { variationText = '↑ +'+variation; variationClass = 'ir-var-up'; }
      else if (variation < 0) { variationText = '↓ '+variation; variationClass = 'ir-var-down'; }
      else variationText = '= 0';
    }

    var $card = $('<div>', { class: 'ir-trend-card' });
    var $head = $('<div>', { class: 'ir-trend-head' });
    $head.append('<h4><i class="fas fa-chart-line text-primary mr-2"></i>Tendencia bimestral</h4>');
    $head.append('<small>Comparación de los cuatro bimestres · notas enteras redondeadas</small>');
    $card.append($head);

    var $body = $('<div>', { class: 'ir-trend-body' });
    $body.append($('<div>', { class: 'ir-trend-chart', html: buildTrendSvg(scores, selectedBimester) }));

    var metrics = [
      { label:'Promedio anual acumulado', value: annual === null ? '—' : annual },
      { label:'Mejor bimestre', value: bestBimester === null ? '—' : bestBimester+'° ('+bestScore+')' },
      { label:'Bimestre seleccionado', value: currentScore === null ? '—' : currentScore },
      { label:'Variación vs. anterior', value: variationText, cls: variationClass }
    ];
    var $metrics = $('<div>', { class:'ir-trend-metrics' });
    metrics.forEach(function(item){
      var $m = $('<div>', { class:'ir-trend-metric' });
      $m.append($('<small>', { text:item.label }));
      $m.append($('<strong>', { text:item.value, class:item.cls || '' }));
      $metrics.append($m);
    });
    $body.append($metrics);
    $body.append($('<div>', { class:'ir-trend-note', text:trendInterpretation(scores) }));
    $card.append($body);

    var $summary = $report.find('.ir-summary-grid').first();
    if ($summary.length) $summary.after($card);
    else $report.find('.ir-heading').first().after($card);
  }

  function loadTrend($report) {
    if ($report.attr('data-trend-loading') === '1' || $report.attr('data-trend-loaded') === '1') return;
    if (!$('#student_id').val() || !$('#academic_year_id').val()) return;
    $report.attr('data-trend-loading','1');

    var $placeholder = $('<div>', { class:'ir-trend-card ir-trend-loading', text:'Cargando tendencia bimestral...' });
    var $summary = $report.find('.ir-summary-grid').first();
    if ($summary.length) $summary.after($placeholder);
    else $report.find('.ir-heading').first().after($placeholder);

    Promise.all([1,2,3,4].map(fetchBimesterScore)).then(function(scores){
      $placeholder.remove();
      renderTrend($report, scores);
      $report.attr('data-trend-loaded','1');
    }).catch(function(){
      $placeholder.text('No se pudo cargar la tendencia bimestral.');
    }).then(function(){
      $report.removeAttr('data-trend-loading');
    });
  }

  function enhanceIndividualReport(root) {
    var $report = $(root);
    if (!$report.length || $report.attr('data-status-enhanced') === '1') return;

    ensureStyles();

    var competencyStates = [];
    $report.find('.ir-card').each(function() {
      var $card = $(this);
      var $avgLabel = $card.find('td').filter(function() {
        return $.trim($(this).text()).toLowerCase() === 'promedio de la competencia';
      }).first();
      if (!$avgLabel.length) return;

      var $avgCell = $avgLabel.next('td');
      var rawScore = parseGradeNumber($avgCell.text());
      var score = roundGrade(rawScore);
      if (score === null) return;

      var $scoreStrong = $avgCell.find('strong').first();
      if ($scoreStrong.length) $scoreStrong.text(score);
      else $avgCell.text(score);

      var status = gradeStatus(score);
      competencyStates.push(status);

      var $header = $card.find('.ir-card-header').first();
      if ($header.length && !$header.find('.ir-comp-status').length) {
        $header.append(statusBadge(status, 'ir-comp-status'));
      }

      $avgCell.find('.ir-status-badge').remove();
      $avgCell.append($('<div>', { class: 'mt-1' }).append(statusBadge(status)));
    });

    var $result = $report.find('.ir-result').first();
    var rawFinalScore = parseGradeNumber($result.find('strong').first().text());
    var finalScore = roundGrade(rawFinalScore);
    if (!competencyStates.length && finalScore === 0) finalScore = null;
    var finalStatus = gradeStatus(finalScore);
    if ($result.length) {
      $result.find('strong').first().text(finalScore === null ? '—' : finalScore);
      $result.addClass('ir-result-status').css({
        borderColor: finalStatus.color,
        boxShadow: 'inset 4px 0 0 ' + finalStatus.color
      });
      $result.find('.ir-final-status').remove();
      $result.append(statusBadge(finalStatus, 'ir-final-status'));
    }

    roundDisplayedCalculationGrades($report);

    if (competencyStates.length && !$report.find('.ir-summary-grid').length) {
      var counts = { good: 0, process: 0, start: 0 };
      competencyStates.forEach(function(status) {
        if (status.letter === 'AD' || status.letter === 'A') counts.good++;
        else if (status.letter === 'B') counts.process++;
        else if (status.letter === 'C') counts.start++;
      });

      var items = [
        { label: 'Competencias evaluadas', value: competencyStates.length, color: '#4e73df' },
        { label: 'Logro esperado / destacado', value: counts.good, color: '#1cc88a' },
        { label: 'En proceso', value: counts.process, color: '#f6c23e' },
        { label: 'En inicio', value: counts.start, color: '#e74a3b' }
      ];
      var $summary = $('<div>', { class: 'ir-summary-grid', 'aria-label': 'Resumen del desempeño' });
      items.forEach(function(item) {
        var $box = $('<div>', { class: 'ir-summary-item' });
        $box.append($('<small>').append($('<span>', { class: 'ir-summary-dot' }).css('backgroundColor', item.color)).append(document.createTextNode(item.label)));
        $box.append($('<strong>', { text: item.value }));
        $summary.append($box);
      });
      $report.find('.ir-heading').first().after($summary);
    }

    $report.attr('data-status-enhanced', '1');
    loadTrend($report);
  }

  function scanIndividualReports() {
    $('.individual-report').each(function() {
      enhanceIndividualReport(this);
    });
  }

  $(scanIndividualReports);

  if (window.MutationObserver) {
    var observer = new MutationObserver(function(mutations) {
      var shouldScan = mutations.some(function(mutation) {
        return mutation.addedNodes && mutation.addedNodes.length;
      });
      if (shouldScan) scanIndividualReports();
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }
})(jQuery);
